-- jaga warga: skema konsolidasi untuk instalasi baru, tanpa data dummy.
-- mencakup akun, wilayah, 30 fitur pengurus, 40 fitur warga, dan inovasi.
-- database proyek telah dimigrasikan melalui dialog sql; jangan menjalankan ulang pada database berisi data tanpa meninjau migrasi.
-- semua data operasional berasal dari pengguna; akun pemilik harus sudah terverifikasi di auth.users.
begin;
create table if not exists public.user_profiles(id uuid primary key references auth.users(id) on delete cascade,username text not null default '',email text not null default '',phone text not null default '',account_role text not null default 'resident' check(account_role in ('super_admin','admin','resident')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.regions(id uuid primary key default gen_random_uuid(),name text not null,rt text not null,rw text not null,address text not null,created_by uuid not null references auth.users(id) on delete cascade,invitation_code uuid not null unique default gen_random_uuid(),created_at timestamptz not null default now());
create table if not exists public.memberships(id uuid primary key default gen_random_uuid(),region_id uuid not null references public.regions(id) on delete cascade,user_id uuid not null references public.user_profiles(id) on delete cascade,role text not null default 'resident' check(role in ('super_admin','admin','resident')),status text not null default 'pending' check(status in ('pending','verified','rejected','suspended')),house_number text not null default '',domicile_path text,review_note text,created_at timestamptz not null default now(),unique(region_id,user_id));
create table if not exists public.reports(id uuid primary key default gen_random_uuid(),region_id uuid not null references public.regions(id) on delete cascade,user_id uuid not null references public.user_profiles(id) on delete cascade,title text not null check(length(trim(title))>0),description text not null,category text not null,priority text not null default 'medium' check(priority in ('critical','high','medium','low')),status text not null default 'pending' check(status in ('pending','valid','duplicate','hoax','assigned','in_progress','resolved')),latitude double precision check(latitude between -90 and 90),longitude double precision check(longitude between -180 and 180),anonymous boolean not null default false,client_request_id uuid,block text not null default '',verification_note text,assigned_to uuid references public.user_profiles(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.sos_alerts(id uuid primary key default gen_random_uuid(),region_id uuid not null references public.regions(id) on delete cascade,user_id uuid not null references public.user_profiles(id) on delete cascade,latitude double precision not null check(latitude between -90 and 90),longitude double precision not null check(longitude between -180 and 180),status text not null default 'active' check(status in ('active','responded','safe','cancelled')),responded_at timestamptz,client_request_id uuid,created_at timestamptz not null default now());
create table if not exists public.audit_logs(id uuid primary key default gen_random_uuid(),region_id uuid references public.regions(id) on delete cascade,actor_id uuid not null references public.user_profiles(id) on delete cascade,action text not null,target_table text not null,target_id uuid,metadata jsonb not null default '{}',created_at timestamptz not null default now());
-- tabel operasional dengan identitas dan wilayah wajib, dibuat tanpa seed.
do $$ declare entry jsonb; definitions jsonb := '[
{"name":"report_categories","columns":"name text not null,default_priority text not null default ''medium'' check(default_priority in (''critical'',''high'',''medium'',''low'')),unique(region_id,name)"},
{"name":"early_warnings","columns":"title text not null,body text not null,severity text not null check(severity in (''critical'',''high'',''medium'',''low'')),affected_blocks text[] not null default ''{}'',expires_at timestamptz"},
{"name":"announcements","columns":"title text not null,body text not null,expires_at timestamptz"},
{"name":"emergency_contacts","columns":"name text not null,service_type text not null,phone text not null check(phone ~ ''^[+0-9 ()-]{3,30}$'')"},
{"name":"water_readings","columns":"station_name text not null,level_cm numeric not null check(level_cm>=0),status text not null check(status in (''safe'',''watch'',''danger'')),measured_at timestamptz not null default now()"},
{"name":"households","columns":"house_number text not null,block text not null default '''',head_name text not null,occupancy text not null default ''occupied'' check(occupancy in (''occupied'',''vacant'',''rented'')),member_count integer not null default 1 check(member_count>=0),latitude double precision check(latitude between -90 and 90),longitude double precision check(longitude between -180 and 180),unique(region_id,house_number)"},
{"name":"family_members","columns":"name text not null,relationship text not null,birth_date date,vulnerabilities text[] not null default ''{}'',notes text not null default '''',unique(id,region_id,user_id)"},
{"name":"guest_visits","columns":"guest_name text not null,origin text not null,start_date date not null,end_date date not null,house_number text not null,notes text not null default '''',status text not null default ''pending'' check(status in (''pending'',''recorded'',''completed'')),check(end_date>=start_date)"},
{"name":"patrol_posts","columns":"name text not null,address text not null,latitude double precision not null check(latitude between -90 and 90),longitude double precision not null check(longitude between -180 and 180),checkin_radius_m integer not null default 100 check(checkin_radius_m between 10 and 1000),qr_token uuid not null unique default gen_random_uuid(),unique(id,region_id)"},
{"name":"inventory_items","columns":"name text not null,quantity integer not null check(quantity>=0),condition text not null check(condition in (''good'',''needs_repair'',''broken'')),location text not null,latitude double precision check(latitude between -90 and 90),longitude double precision check(longitude between -180 and 180)"},
{"name":"assembly_points","columns":"name text not null,address text not null,point_type text not null check(point_type in (''assembly'',''shelter'')),capacity integer not null check(capacity>=0),occupancy integer not null default 0 check(occupancy>=0 and occupancy<=capacity),active boolean not null default true,latitude double precision not null check(latitude between -90 and 90),longitude double precision not null check(longitude between -180 and 180),unique(id,region_id)"},
{"name":"safe_routes","columns":"name text not null,notes text not null default '''',active boolean not null default true,last_checked_at timestamptz not null default now(),unique(id,region_id)"},
{"name":"cash_transactions","columns":"transaction_type text not null check(transaction_type in (''income'',''expense'')),amount numeric(16,2) not null check(amount>0),description text not null,transaction_date date not null default current_date,proof_path text"},
{"name":"polls","columns":"question text not null,description text not null default '''',closes_at timestamptz not null,status text not null default ''active'' check(status in (''active'',''closed'')),unique(id,region_id)"},
{"name":"live_locations","columns":"latitude double precision not null check(latitude between -90 and 90),longitude double precision not null check(longitude between -180 and 180),expires_at timestamptz not null,active boolean not null default true,updated_at timestamptz not null default now(),unique(id,region_id)"},
{"name":"volunteer_offers","columns":"help_type text not null check(help_type in (''vehicle'',''equipment'',''volunteer'',''food'',''other'')),description text not null,contact text not null,available boolean not null default true"},
{"name":"service_listings","columns":"name text not null,skill text not null,description text not null,phone text not null,active boolean not null default true"},
{"name":"mitigation_guides","columns":"title text not null,scenario text not null check(scenario in (''flood'',''earthquake'',''fire'',''first_aid'',''other'')),body text not null check(length(body) between 1 and 50000),source_url text,updated_at timestamptz not null default now()"},
{"name":"go_bag_items","columns":"name text not null,quantity integer not null default 1 check(quantity>0),prepared boolean not null default false,unique(region_id,user_id,name)"},
{"name":"letter_requests","columns":"letter_type text not null,purpose text not null,status text not null default ''pending'' check(status in (''pending'',''in_progress'',''resolved'',''rejected'')),admin_note text not null default '''',document_path text"},
{"name":"notification_preferences","columns":"emergency_alerts boolean not null default true,announcements boolean not null default true,patrol_reminders boolean not null default true,radius_m integer not null default 1000 check(radius_m between 100 and 50000),battery_saver boolean not null default false,push_token text,unique(region_id,user_id)"},
{"name":"notifications","columns":"kind text not null,title text not null,body text not null,entity_id uuid,read_at timestamptz"},
{"name":"webhook_integrations","columns":"name text not null,endpoint_url text not null check(endpoint_url ~ ''^https://[^[:space:]]+$''),events text[] not null check(events <@ array[''sos_created'',''report_created'',''early_warning'']::text[] and cardinality(events)>0),enabled boolean not null default true,unique(id,region_id)"}
]'::jsonb;
begin for entry in select * from jsonb_array_elements(definitions) loop execute format('create table if not exists public.%I (id uuid primary key default gen_random_uuid(),region_id uuid not null references public.regions(id) on delete cascade,user_id uuid not null references public.user_profiles(id) on delete cascade,%s,created_at timestamptz not null default now())',entry->>'name',entry->>'columns');end loop;end; $$;
create table if not exists public.family_safety(id uuid primary key default gen_random_uuid(),region_id uuid not null references public.regions(id) on delete cascade,user_id uuid not null references public.user_profiles(id) on delete cascade,family_member_id uuid not null unique,status text not null check(status in ('safe','needs_help')),note text not null default '',updated_at timestamptz not null default now(),created_at timestamptz not null default now(),foreign key(family_member_id,region_id,user_id) references public.family_members(id,region_id,user_id) on delete cascade);
create table if not exists public.evacuation_requests(id uuid primary key default gen_random_uuid(),region_id uuid not null references public.regions(id) on delete cascade,user_id uuid not null references public.user_profiles(id) on delete cascade,family_member_id uuid not null,condition text not null,pickup_address text not null,latitude double precision check(latitude between -90 and 90),longitude double precision check(longitude between -180 and 180),status text not null default 'pending' check(status in ('pending','in_progress','resolved','cancelled')),admin_note text not null default '',created_at timestamptz not null default now(),foreign key(family_member_id,region_id,user_id) references public.family_members(id,region_id,user_id) on delete cascade);
create table if not exists public.patrol_shifts(id uuid primary key default gen_random_uuid(),region_id uuid not null references public.regions(id) on delete cascade,user_id uuid not null references public.user_profiles(id) on delete cascade,post_id uuid not null,title text not null,starts_at timestamptz not null,ends_at timestamptz not null check(ends_at>starts_at),created_at timestamptz not null default now(),foreign key(post_id,region_id) references public.patrol_posts(id,region_id) on delete cascade,unique(id,region_id));
create table if not exists public.patrol_assignments(id uuid primary key default gen_random_uuid(),region_id uuid not null references public.regions(id) on delete cascade,user_id uuid not null references public.user_profiles(id) on delete cascade,shift_id uuid not null,created_at timestamptz not null default now(),foreign key(shift_id,region_id) references public.patrol_shifts(id,region_id) on delete cascade,foreign key(region_id,user_id) references public.memberships(region_id,user_id) on delete cascade,unique(shift_id,user_id),unique(id,region_id,user_id));
create table if not exists public.patrol_attendance(id uuid primary key default gen_random_uuid(),region_id uuid not null references public.regions(id) on delete cascade,user_id uuid not null references public.user_profiles(id) on delete cascade,assignment_id uuid not null unique,latitude double precision not null check(latitude between -90 and 90),longitude double precision not null check(longitude between -180 and 180),method text not null check(method in ('gps','qr')),created_at timestamptz not null default now(),foreign key(assignment_id,region_id,user_id) references public.patrol_assignments(id,region_id,user_id) on delete cascade);
create table if not exists public.shift_swap_requests(id uuid primary key default gen_random_uuid(),region_id uuid not null references public.regions(id) on delete cascade,user_id uuid not null references public.user_profiles(id) on delete cascade,own_assignment_id uuid not null references public.patrol_assignments(id) on delete cascade,target_assignment_id uuid not null references public.patrol_assignments(id) on delete cascade,recipient_id uuid not null references public.user_profiles(id) on delete cascade,status text not null default 'pending' check(status in ('pending','approved','rejected','cancelled')),created_at timestamptz not null default now(),check(own_assignment_id<>target_assignment_id));
create table if not exists public.logistics_needs(id uuid primary key default gen_random_uuid(),region_id uuid not null references public.regions(id) on delete cascade,user_id uuid not null references public.user_profiles(id) on delete cascade,shelter_id uuid not null,name text not null,unit text not null,needed numeric not null check(needed>=0),available numeric not null default 0 check(available>=0),notes text not null default '',created_at timestamptz not null default now(),foreign key(shelter_id,region_id) references public.assembly_points(id,region_id) on delete cascade);
create table if not exists public.safe_route_points(id uuid primary key default gen_random_uuid(),region_id uuid not null references public.regions(id) on delete cascade,user_id uuid not null references public.user_profiles(id) on delete cascade,route_id uuid not null,sequence integer not null check(sequence>=0),latitude double precision not null check(latitude between -90 and 90),longitude double precision not null check(longitude between -180 and 180),lit boolean not null default false,notes text not null default '',created_at timestamptz not null default now(),foreign key(route_id,region_id) references public.safe_routes(id,region_id) on delete cascade,unique(route_id,sequence));
create table if not exists public.payment_confirmations(id uuid primary key default gen_random_uuid(),region_id uuid not null references public.regions(id) on delete cascade,user_id uuid not null references public.user_profiles(id) on delete cascade,amount numeric(16,2) not null check(amount>0),period text not null,purpose text not null,proof_path text not null,status text not null default 'pending' check(status in ('pending','approved','rejected')),admin_note text not null default '',transaction_id uuid unique references public.cash_transactions(id) on delete set null,created_at timestamptz not null default now());
create table if not exists public.poll_options(id uuid primary key default gen_random_uuid(),region_id uuid not null references public.regions(id) on delete cascade,user_id uuid not null references public.user_profiles(id) on delete cascade,poll_id uuid not null,label text not null,created_at timestamptz not null default now(),foreign key(poll_id,region_id) references public.polls(id,region_id) on delete cascade,unique(poll_id,label),unique(id,poll_id));
create table if not exists public.poll_votes(id uuid primary key default gen_random_uuid(),region_id uuid not null references public.regions(id) on delete cascade,user_id uuid not null references public.user_profiles(id) on delete cascade,poll_id uuid not null,option_id uuid not null,created_at timestamptz not null default now(),foreign key(poll_id,region_id) references public.polls(id,region_id) on delete cascade,foreign key(option_id,poll_id) references public.poll_options(id,poll_id) on delete cascade,unique(poll_id,user_id));
create table if not exists public.location_recipients(id uuid primary key default gen_random_uuid(),region_id uuid not null references public.regions(id) on delete cascade,user_id uuid not null references public.user_profiles(id) on delete cascade,share_id uuid not null,created_at timestamptz not null default now(),foreign key(share_id,region_id) references public.live_locations(id,region_id) on delete cascade,foreign key(region_id,user_id) references public.memberships(region_id,user_id) on delete cascade,unique(share_id,user_id));
create table if not exists public.webhook_deliveries(id uuid primary key default gen_random_uuid(),region_id uuid not null references public.regions(id) on delete cascade,integration_id uuid not null,event text not null,entity_id uuid,payload jsonb not null,status text not null default 'pending' check(status in ('pending','processing','sent','failed')),attempts integer not null default 0,http_status integer,error_message text,created_at timestamptz not null default now(),delivered_at timestamptz,foreign key(integration_id,region_id) references public.webhook_integrations(id,region_id) on delete cascade,unique(integration_id,event,entity_id));
-- anak laporan: id dan pemilik wajib, laporan dihapus secara cascade.
do $$ declare t text;cols text;begin for t,cols in values
('report_media','storage_path text not null unique,media_type text not null check(media_type in (''photo'',''video'',''audio'')),mime_type text not null,byte_size bigint not null check(byte_size>0 and byte_size<=52428800)'),
('report_updates','status text not null,note text not null default '''',proof_path text'),
('report_comments','body text not null check(length(trim(body)) between 1 and 10000),official boolean not null default false'),
('report_confirmations','response text not null check(response in (''seen'',''resolved'',''not_seen'')),latitude double precision,longitude double precision,unique(report_id,user_id)'),
('report_escalations','destination text not null check(destination in (''rw'',''kelurahan'',''damkar'',''bpbd'')),summary text not null'),
('incident_debriefs','went_well text not null,challenges text not null,recommendations text not null,unique(report_id)'),
('report_ratings','rating integer not null check(rating between 1 and 5),review text not null default '''',unique(report_id)')
loop execute format('create table if not exists public.%I(id uuid primary key default gen_random_uuid(),report_id uuid not null references public.reports(id) on delete cascade,user_id uuid not null references public.user_profiles(id) on delete cascade,%s,created_at timestamptz not null default now())',t,cols);end loop;end; $$;
create index if not exists reports_user_idx on public.reports(user_id);
create index if not exists sos_user_idx on public.sos_alerts(user_id);
create index if not exists memberships_user_region_idx on public.memberships(user_id,region_id);
create unique index if not exists reports_client_request_idx on public.reports(user_id,client_request_id) where client_request_id is not null;
create unique index if not exists sos_client_request_idx on public.sos_alerts(user_id,client_request_id) where client_request_id is not null;
create unique index if not exists shift_swap_pending_idx on public.shift_swap_requests(own_assignment_id,target_assignment_id) where status='pending';
-- helper terkontrol; email/peran tidak dapat diubah melalui update profil biasa.
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.user_profiles(id,username,email,phone,account_role) values(new.id,coalesce(new.raw_user_meta_data->>'username',''),coalesce(new.email,''),coalesce(new.raw_user_meta_data->>'phone',''),case when lower(new.email)='accgameskuy@gmail.com' and new.email_confirmed_at is not null then 'super_admin' else 'resident' end) on conflict(id) do nothing;return new;end; $$;
create or replace function public.sync_verified_account() returns trigger language plpgsql security definer set search_path='' as $$ begin update public.user_profiles set email=coalesce(new.email,''),updated_at=now(),account_role=case when lower(new.email)='accgameskuy@gmail.com' and new.email_confirmed_at is not null then 'super_admin' when lower(coalesce(old.email,''))='accgameskuy@gmail.com' and lower(coalesce(new.email,''))<>'accgameskuy@gmail.com' then 'resident' else account_role end where id=new.id;if lower(coalesce(old.email,''))='accgameskuy@gmail.com' and lower(coalesce(new.email,''))<>'accgameskuy@gmail.com' then update public.memberships set role='resident' where user_id=new.id;elsif lower(new.email)='accgameskuy@gmail.com' and new.email_confirmed_at is not null then update public.memberships set role='super_admin',status='verified' where user_id=new.id;end if;return new;end; $$;
-- mengganti trigger auth tanpa menghapus akun pengguna.
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
drop trigger if exists on_auth_user_verified_jaga_warga on auth.users;
create trigger on_auth_user_verified_jaga_warga after update of email,email_confirmed_at on auth.users for each row execute function public.sync_verified_account();
insert into public.user_profiles(id,username,email,account_role) select id,coalesce(raw_user_meta_data->>'username',''),coalesce(email,''),case when lower(email)='accgameskuy@gmail.com' and email_confirmed_at is not null then 'super_admin' else 'resident' end from auth.users on conflict(id) do nothing;
update public.user_profiles p set account_role='super_admin' from auth.users u where p.id=u.id and lower(u.email)='accgameskuy@gmail.com' and u.email_confirmed_at is not null;
create or replace function public.is_super_admin() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.user_profiles p join auth.users u on u.id=p.id where p.id=auth.uid() and p.account_role='super_admin' and u.email_confirmed_at is not null); $$;
create or replace function public.is_region_member(target_region uuid) returns boolean language sql stable security definer set search_path='' as $$ select public.is_super_admin() or exists(select 1 from public.memberships where region_id=target_region and user_id=auth.uid() and status='verified'); $$;
create or replace function public.is_region_admin(target_region uuid) returns boolean language sql stable security definer set search_path='' as $$ select public.is_super_admin() or exists(select 1 from public.memberships m join public.user_profiles p on p.id=m.user_id where m.region_id=target_region and m.user_id=auth.uid() and m.status='verified' and m.role in ('super_admin','admin') and p.account_role in ('super_admin','admin')); $$;
create or replace function public.can_read_report(target_report uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.reports where id=target_report and public.is_region_member(region_id)); $$;
create or replace function public.can_manage_report(target_report uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.reports where id=target_report and public.is_region_admin(region_id)); $$;
create or replace function public.owns_report(target_report uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.reports where id=target_report and user_id=auth.uid() and public.is_region_member(region_id)); $$;
create or replace function public.owns_location_share(target_share uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.live_locations where id=target_share and user_id=auth.uid() and public.is_region_member(region_id)); $$;
create or replace function public.is_location_recipient(target_share uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.location_recipients r join public.live_locations l on l.id=r.share_id where r.share_id=target_share and r.user_id=auth.uid() and l.active and l.expires_at>now() and public.is_region_member(l.region_id)); $$;
create or replace function public.create_region(region_name text,rt_number text,rw_number text,region_address text) returns uuid language plpgsql security definer set search_path='' as $$ declare result_id uuid;role_value text;begin select account_role into role_value from public.user_profiles where id=auth.uid();if role_value is null or role_value not in ('super_admin','admin') then raise exception 'Pembuatan wilayah hanya untuk akun pengurus';end if;if length(trim(coalesce(region_name,'')))=0 or length(trim(coalesce(rt_number,'')))=0 or length(trim(coalesce(rw_number,'')))=0 or length(trim(coalesce(region_address,'')))=0 then raise exception 'Data wilayah wajib diisi';end if;insert into public.regions(name,rt,rw,address,created_by) values(trim(region_name),trim(rt_number),trim(rw_number),trim(region_address),auth.uid()) returning id into result_id;insert into public.memberships(region_id,user_id,role,status) values(result_id,auth.uid(),role_value,'verified');return result_id;end; $$;
create or replace function public.join_region(invite uuid,house text,proof_path text) returns uuid language plpgsql security definer set search_path='' as $$ declare region_value uuid;result_id uuid;begin if auth.uid() is null then raise exception 'Silakan masuk';end if;if length(trim(coalesce(house,'')))=0 or proof_path not like auth.uid()::text||'/%' then raise exception 'Nomor rumah dan bukti domisili milik Anda wajib diisi';end if;select id into region_value from public.regions where invitation_code=invite;if region_value is null then raise exception 'Kode undangan tidak ditemukan';end if;insert into public.memberships(region_id,user_id,house_number,domicile_path) values(region_value,auth.uid(),trim(house),proof_path) returning id into result_id;return result_id;end; $$;
create or replace function public.set_admin_by_email(target_email text,target_region uuid,new_role text default 'admin') returns uuid language plpgsql security definer set search_path='' as $$ declare target_user uuid;result_id uuid;begin if not public.is_super_admin() then raise exception 'Hanya Super Admin dapat mengatur Admin';end if;if new_role not in ('admin','resident') then raise exception 'Peran tidak valid';end if;select id into target_user from auth.users where lower(email)=lower(trim(target_email)) and email_confirmed_at is not null;if target_user is null then raise exception 'Akun belum terdaftar atau email belum terverifikasi';end if;if target_user=auth.uid() or exists(select 1 from public.user_profiles where id=target_user and account_role='super_admin') then raise exception 'Peran Super Admin tidak dapat diubah';end if;insert into public.memberships(region_id,user_id,role,status) values(target_region,target_user,new_role,'verified') on conflict(region_id,user_id) do update set role=excluded.role,status='verified' returning id into result_id;update public.user_profiles set account_role=case when exists(select 1 from public.memberships where user_id=target_user and role='admin' and status='verified') then 'admin' else 'resident' end,updated_at=now() where id=target_user;insert into public.audit_logs(region_id,actor_id,action,target_table,target_id,metadata) values(target_region,auth.uid(),'set_admin_role','memberships',result_id,jsonb_build_object('role',new_role));return result_id;end; $$;
create or replace function public.review_membership(target_membership uuid,new_status text,note text default '') returns void language plpgsql security definer set search_path='' as $$ declare m public.memberships;begin select * into m from public.memberships where id=target_membership for update;if m.id is null or not public.is_region_admin(m.region_id) then raise exception 'Tidak memiliki akses verifikasi';end if;if new_status not in ('verified','rejected','suspended') or (new_status in ('rejected','suspended') and length(trim(note))=0) then raise exception 'Status atau alasan tidak valid';end if;if exists(select 1 from public.user_profiles where id=m.user_id and account_role='super_admin') then raise exception 'Super Admin tidak dapat ditangguhkan';end if;if m.role='admin' and not public.is_super_admin() then raise exception 'Hanya Super Admin dapat meninjau Admin';end if;update public.memberships set status=new_status,review_note=nullif(trim(note),'') where id=m.id;insert into public.audit_logs(region_id,actor_id,action,target_table,target_id,metadata) values(m.region_id,auth.uid(),'review_membership','memberships',m.id,jsonb_build_object('status',new_status,'note',note));end; $$;
create or replace function public.get_region_feed(target_region uuid) returns setof jsonb language sql stable security definer set search_path='' as $$ select (to_jsonb(r)-'user_id'-'client_request_id')||jsonb_build_object('user_id',case when not r.anonymous or r.user_id=auth.uid() or public.is_region_admin(r.region_id) then r.user_id else null end) from public.reports r where r.region_id=target_region and public.is_region_member(target_region) order by r.created_at desc; $$;
create or replace function public.get_report_detail(target_report uuid) returns jsonb language sql stable security definer set search_path='' as $$ select (to_jsonb(r)-'user_id'-'client_request_id')||jsonb_build_object('user_id',case when not r.anonymous or r.user_id=auth.uid() or public.is_region_admin(r.region_id) then r.user_id else null end) from public.reports r where r.id=target_report and public.can_read_report(target_report); $$;
create or replace function public.get_crowd_summary(target_report uuid) returns jsonb language sql stable security definer set search_path='' as $$ select jsonb_build_object('seen',count(*) filter(where response='seen'),'resolved',count(*) filter(where response='resolved'),'not_seen',count(*) filter(where response='not_seen')) from public.report_confirmations where report_id=target_report and public.can_read_report(target_report); $$;
create or replace function public.get_poll_results(target_poll uuid) returns table(option_id uuid,label text,votes bigint) language sql stable security definer set search_path='' as $$ select o.id,o.label,count(v.id) from public.poll_options o join public.polls p on p.id=o.poll_id left join public.poll_votes v on v.option_id=o.id where p.id=target_poll and public.is_region_member(p.region_id) group by o.id,o.label order by o.created_at; $$;
create or replace function public.log_report_progress() returns trigger language plpgsql security definer set search_path='' as $$ begin if tg_op='INSERT' then insert into public.report_updates(report_id,user_id,status,note) values(new.id,new.user_id,new.status,'Laporan dikirim');elsif new.status is distinct from old.status or new.assigned_to is distinct from old.assigned_to then insert into public.report_updates(report_id,user_id,status,note) values(new.id,coalesce(auth.uid(),new.user_id),new.status,coalesce(new.verification_note,''));end if;return new;end; $$;
create trigger log_report_progress after insert or update on public.reports for each row execute function public.log_report_progress();
create or replace function public.update_report_progress(target_report uuid,new_status text,note text,assignee uuid default null,proof text default null) returns void language plpgsql security definer set search_path='' as $$ declare r public.reports;changed boolean;begin select * into r from public.reports where id=target_report for update;if r.id is null or not public.is_region_admin(r.region_id) then raise exception 'Tidak memiliki akses laporan';end if;if new_status not in ('valid','duplicate','hoax','assigned','in_progress','resolved') or length(trim(coalesce(note,'')))=0 then raise exception 'Status dan catatan penanganan wajib diisi';end if;if assignee is not null and not exists(select 1 from public.memberships where region_id=r.region_id and user_id=assignee and status='verified') then raise exception 'Petugas harus anggota terverifikasi';end if;if new_status='assigned' and assignee is null then raise exception 'Pilih petugas';end if;if proof is not null and proof not like auth.uid()::text||'/%' then raise exception 'Bukti harus milik pengunggah';end if;changed:=r.status is distinct from new_status or r.assigned_to is distinct from coalesce(assignee,r.assigned_to);update public.reports set status=new_status,verification_note=trim(note),assigned_to=coalesce(assignee,assigned_to),updated_at=now() where id=r.id;if not changed then insert into public.report_updates(report_id,user_id,status,note,proof_path) values(r.id,auth.uid(),new_status,trim(note),proof);elsif proof is not null then update public.report_updates set proof_path=proof where id=(select id from public.report_updates where report_id=r.id order by created_at desc limit 1);end if;end; $$;
create or replace function public.close_own_sos(target_sos uuid,new_status text) returns void language plpgsql security definer set search_path='' as $$ begin if new_status not in ('safe','cancelled') then raise exception 'Status tidak valid';end if;update public.sos_alerts set status=new_status where id=target_sos and user_id=auth.uid() and status in ('active','responded');if not found then raise exception 'SOS aktif tidak ditemukan';end if;end; $$;
create or replace function public.review_service_request(request_table text,target_request uuid,new_status text,note text default '',document text default null) returns void language plpgsql security definer set search_path='' as $$ declare target_region uuid;begin if request_table not in ('evacuation_requests','guest_visits','letter_requests') then raise exception 'Layanan tidak valid';end if;execute format('select region_id from public.%I where id=$1 for update',request_table) into target_region using target_request;if target_region is null or not public.is_region_admin(target_region) then raise exception 'Tidak memiliki akses layanan';end if;if request_table='guest_visits' then if new_status not in ('recorded','completed') then raise exception 'Status tamu tidak valid';end if;update public.guest_visits set status=new_status where id=target_request;elsif request_table='evacuation_requests' then if new_status not in ('in_progress','resolved','cancelled') then raise exception 'Status evakuasi tidak valid';end if;update public.evacuation_requests set status=new_status,admin_note=note where id=target_request;else if new_status not in ('in_progress','resolved','rejected') then raise exception 'Status surat tidak valid';end if;if document is not null and document not like auth.uid()::text||'/%' then raise exception 'Dokumen harus milik pengunggah';end if;update public.letter_requests set status=new_status,admin_note=note,document_path=coalesce(document,document_path) where id=target_request;end if;end; $$;
create or replace function public.review_payment(target_payment uuid,approve boolean,note text default '') returns void language plpgsql security definer set search_path='' as $$ declare p public.payment_confirmations;transaction_value uuid;begin select * into p from public.payment_confirmations where id=target_payment for update;if p.id is null or not public.is_region_admin(p.region_id) then raise exception 'Tidak memiliki akses pembayaran';end if;if p.status<>'pending' then raise exception 'Pembayaran sudah ditinjau';end if;if not approve and length(trim(note))=0 then raise exception 'Alasan penolakan wajib diisi';end if;if approve then insert into public.cash_transactions(region_id,user_id,transaction_type,amount,description,proof_path) values(p.region_id,auth.uid(),'income',p.amount,p.purpose||' · '||p.period,p.proof_path) returning id into transaction_value;end if;update public.payment_confirmations set status=case when approve then 'approved' else 'rejected' end,admin_note=note,transaction_id=transaction_value where id=p.id;end; $$;
create or replace function public.checkin_patrol(target_assignment uuid,lat double precision,lng double precision,token uuid default null) returns uuid language plpgsql security definer set search_path='' as $$ declare a public.patrol_assignments;s public.patrol_shifts;p public.patrol_posts;distance_m double precision;result_id uuid;begin select * into a from public.patrol_assignments where id=target_assignment;if a.id is null or a.user_id<>auth.uid() or not public.is_region_member(a.region_id) then raise exception 'Anda tidak ditugaskan';end if;select * into s from public.patrol_shifts where id=a.shift_id;select * into p from public.patrol_posts where id=s.post_id;if now()<s.starts_at-interval '30 minutes' or now()>s.ends_at then raise exception 'Di luar waktu ronda';end if;if lat is null or lng is null or lat not between -90 and 90 or lng not between -180 and 180 then raise exception 'Koordinat tidak valid';end if;distance_m:=6371000*2*asin(sqrt(least(1.0,power(sin(radians(lat-p.latitude)/2),2)+cos(radians(lat))*cos(radians(p.latitude))*power(sin(radians(lng-p.longitude)/2),2))));if distance_m>p.checkin_radius_m then raise exception 'Di luar radius pos';end if;if token is not null and token<>p.qr_token then raise exception 'QR pos tidak cocok';end if;insert into public.patrol_attendance(region_id,user_id,assignment_id,latitude,longitude,method) values(a.region_id,auth.uid(),a.id,lat,lng,case when token is null then 'gps' else 'qr' end) returning id into result_id;return result_id;end; $$;
create or replace function public.request_shift_swap(own_assignment uuid,target_assignment uuid) returns uuid language plpgsql security definer set search_path='' as $$ declare a public.patrol_assignments;b public.patrol_assignments;result_id uuid;begin select * into a from public.patrol_assignments where id=own_assignment;select * into b from public.patrol_assignments where id=target_assignment;if a.id is null or b.id is null or a.user_id<>auth.uid() or b.user_id=auth.uid() or a.region_id<>b.region_id or a.shift_id=b.shift_id or not public.is_region_member(a.region_id) then raise exception 'Pasangan jadwal tidak valid';end if;if exists(select 1 from public.patrol_shifts where id in (a.shift_id,b.shift_id) and starts_at<=now()) then raise exception 'Giliran telah dimulai';end if;insert into public.shift_swap_requests(region_id,user_id,own_assignment_id,target_assignment_id,recipient_id) values(a.region_id,auth.uid(),a.id,b.id,b.user_id) returning id into result_id;return result_id;end; $$;
create or replace function public.respond_shift_swap(target_swap uuid,approve boolean) returns void language plpgsql security definer set search_path='' as $$ declare r public.shift_swap_requests;a public.patrol_assignments;b public.patrol_assignments;begin select * into r from public.shift_swap_requests where id=target_swap for update;if r.id is null or r.recipient_id<>auth.uid() or r.status<>'pending' or not public.is_region_member(r.region_id) then raise exception 'Permintaan tidak dapat diproses';end if;if not approve then update public.shift_swap_requests set status='rejected' where id=r.id;return;end if;perform id from public.patrol_assignments where id in (r.own_assignment_id,r.target_assignment_id) order by id for update;select * into a from public.patrol_assignments where id=r.own_assignment_id;select * into b from public.patrol_assignments where id=r.target_assignment_id;if a.user_id<>r.user_id or b.user_id<>auth.uid() or a.shift_id=b.shift_id then raise exception 'Jadwal berubah';end if;if exists(select 1 from public.patrol_shifts where id in (a.shift_id,b.shift_id) and starts_at<=now()) or exists(select 1 from public.patrol_attendance where assignment_id in (a.id,b.id)) then raise exception 'Giliran telah dimulai';end if;if exists(select 1 from public.patrol_assignments where (shift_id=b.shift_id and user_id=a.user_id) or (shift_id=a.shift_id and user_id=b.user_id)) then raise exception 'Jadwal tujuan sudah berisi penugasan warga ini';end if;update public.patrol_assignments set shift_id=case when id=a.id then b.shift_id else a.shift_id end where id in (a.id,b.id);update public.shift_swap_requests set status='approved' where id=r.id;end; $$;
-- rls: tanpa policy anon, data hanya untuk akun berhak.
do $$ declare t text;begin for t in select tablename from pg_tables where schemaname='public' and tablename in ('regions','user_profiles','memberships','reports','sos_alerts','audit_logs','report_categories','report_media','report_updates','report_comments','report_confirmations','report_escalations','incident_debriefs','report_ratings','early_warnings','announcements','emergency_contacts','water_readings','households','family_members','family_safety','evacuation_requests','guest_visits','patrol_posts','patrol_shifts','patrol_assignments','patrol_attendance','shift_swap_requests','inventory_items','assembly_points','logistics_needs','safe_routes','safe_route_points','cash_transactions','payment_confirmations','polls','poll_options','poll_votes','live_locations','location_recipients','volunteer_offers','service_listings','mitigation_guides','go_bag_items','letter_requests','notification_preferences','notifications','webhook_integrations','webhook_deliveries') loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon',t);execute format('grant select on public.%I to authenticated',t);if exists(select 1 from information_schema.columns where table_schema='public' and table_name=t and column_name='region_id') then execute format('create index if not exists %I on public.%I(region_id,created_at desc)',t||'_region_time_idx',t);elsif exists(select 1 from information_schema.columns where table_schema='public' and table_name=t and column_name='report_id') then execute format('create index if not exists %I on public.%I(report_id,created_at)',t||'_report_time_idx',t);end if;end loop;end; $$;
create policy authenticated_select_own_profile on public.user_profiles for select to authenticated using(id=auth.uid());
create policy authenticated_select_region_profiles on public.user_profiles for select to authenticated using(public.is_super_admin() or exists(select 1 from public.memberships m where m.user_id=user_profiles.id and public.is_region_admin(m.region_id)));
create policy authenticated_update_own_profile on public.user_profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
revoke update on public.user_profiles from authenticated;grant update(username,phone,updated_at) on public.user_profiles to authenticated;
create policy authenticated_select_member_region on public.regions for select to authenticated using(created_by=auth.uid() or public.is_region_member(id));
create policy authenticated_update_admin_region on public.regions for update to authenticated using(public.is_region_admin(id)) with check(public.is_region_admin(id));grant update on public.regions to authenticated;
create policy authenticated_select_own_or_admin_membership on public.memberships for select to authenticated using(user_id=auth.uid() or public.is_region_admin(region_id));
create policy authenticated_select_own_or_admin_report on public.reports for select to authenticated using(user_id=auth.uid() or public.is_region_admin(region_id));
create policy authenticated_insert_member_report on public.reports for insert to authenticated with check(user_id=auth.uid() and public.is_region_member(region_id) and status='pending' and assigned_to is null and verification_note is null);
create policy authenticated_update_admin_report on public.reports for update to authenticated using(public.is_region_admin(region_id)) with check(public.is_region_admin(region_id));grant insert,update on public.reports to authenticated;
create policy authenticated_select_own_or_admin_sos on public.sos_alerts for select to authenticated using(user_id=auth.uid() or public.is_region_admin(region_id));
create policy authenticated_insert_member_sos on public.sos_alerts for insert to authenticated with check(user_id=auth.uid() and public.is_region_member(region_id) and status='active' and responded_at is null);
create policy authenticated_update_admin_sos on public.sos_alerts for update to authenticated using(public.is_region_admin(region_id)) with check(public.is_region_admin(region_id));grant insert,update on public.sos_alerts to authenticated;
create policy authenticated_select_admin_audit on public.audit_logs for select to authenticated using(public.is_region_admin(region_id));
-- informasi wilayah: anggota membaca; pengurus membuat/memperbarui/menghapus.
do $$ declare t text;begin foreach t in array array['report_categories','early_warnings','announcements','emergency_contacts','water_readings','patrol_posts','patrol_shifts','inventory_items','assembly_points','logistics_needs','safe_routes','safe_route_points','cash_transactions','polls','poll_options','mitigation_guides'] loop execute format('create policy authenticated_select_region_data on public.%I for select to authenticated using(public.is_region_member(region_id))',t);execute format('create policy authenticated_insert_admin_data on public.%I for insert to authenticated with check(public.is_region_admin(region_id) and user_id=auth.uid())',t);execute format('create policy authenticated_update_admin_data on public.%I for update to authenticated using(public.is_region_admin(region_id)) with check(public.is_region_admin(region_id))',t);execute format('create policy authenticated_delete_admin_data on public.%I for delete to authenticated using(public.is_region_admin(region_id))',t);execute format('grant insert,update,delete on public.%I to authenticated',t);end loop;end; $$;
-- keluarga pribadi, bantuan/jasa yang dibagikan pemilik, dan permintaan warga.
do $$ declare t text;begin foreach t in array array['family_members','family_safety','go_bag_items','volunteer_offers','service_listings'] loop execute format('create policy authenticated_select_own_or_admin_data on public.%I for select to authenticated using((user_id=auth.uid() and public.is_region_member(region_id)) or public.is_region_admin(region_id)%s)',t,case when t in ('volunteer_offers','service_listings') then ' or public.is_region_member(region_id)' else '' end);execute format('create policy authenticated_insert_own_data on public.%I for insert to authenticated with check(user_id=auth.uid() and public.is_region_member(region_id))',t);execute format('create policy authenticated_update_own_or_admin_data on public.%I for update to authenticated using((user_id=auth.uid() and public.is_region_member(region_id)) or public.is_region_admin(region_id)) with check((user_id=auth.uid() and public.is_region_member(region_id)) or public.is_region_admin(region_id))',t);execute format('create policy authenticated_delete_own_data on public.%I for delete to authenticated using(user_id=auth.uid() and public.is_region_member(region_id))',t);execute format('grant insert,update,delete on public.%I to authenticated',t);end loop;foreach t in array array['evacuation_requests','guest_visits','payment_confirmations','letter_requests'] loop execute format('create policy authenticated_select_own_or_admin_requests on public.%I for select to authenticated using((user_id=auth.uid() and public.is_region_member(region_id)) or public.is_region_admin(region_id))',t);execute format('create policy authenticated_insert_own_requests on public.%I for insert to authenticated with check(user_id=auth.uid() and public.is_region_member(region_id) and status=''pending'')',t);execute format('grant insert on public.%I to authenticated',t);execute format('revoke update,delete on public.%I from authenticated',t);end loop;end; $$;
create policy authenticated_select_own_or_admin_households on public.households for select to authenticated using((user_id=auth.uid() and public.is_region_member(region_id)) or public.is_region_admin(region_id));
create policy authenticated_insert_admin_households on public.households for insert to authenticated with check(public.is_region_admin(region_id) and exists(select 1 from public.memberships where region_id=households.region_id and user_id=households.user_id and status='verified'));
create policy authenticated_update_admin_households on public.households for update to authenticated using(public.is_region_admin(region_id)) with check(public.is_region_admin(region_id));
create policy authenticated_delete_admin_households on public.households for delete to authenticated using(public.is_region_admin(region_id));grant insert,update,delete on public.households to authenticated;
do $$ declare t text;begin foreach t in array array['report_media','report_updates','report_comments','report_confirmations','report_escalations','incident_debriefs','report_ratings'] loop execute format('create policy authenticated_select_report_children on public.%I for select to authenticated using(%s)',t,case when t in ('report_confirmations','report_ratings') then '(user_id=auth.uid() and public.can_read_report(report_id)) or public.can_manage_report(report_id)' else 'public.can_read_report(report_id)' end);end loop;end; $$;
create policy authenticated_insert_report_media on public.report_media for insert to authenticated with check(user_id=auth.uid() and (public.owns_report(report_id) or public.can_manage_report(report_id)) and storage_path like auth.uid()::text||'/%');grant insert on public.report_media to authenticated;
create policy authenticated_delete_own_report_media on public.report_media for delete to authenticated using(user_id=auth.uid() and public.owns_report(report_id));grant delete on public.report_media to authenticated;
create policy authenticated_insert_report_comments on public.report_comments for insert to authenticated with check(user_id=auth.uid() and public.can_read_report(report_id) and (not official or public.can_manage_report(report_id)));grant insert on public.report_comments to authenticated;
create policy authenticated_delete_own_report_comments on public.report_comments for delete to authenticated using(user_id=auth.uid() and public.can_read_report(report_id));grant delete on public.report_comments to authenticated;
create policy authenticated_insert_own_confirmation on public.report_confirmations for insert to authenticated with check(user_id=auth.uid() and public.can_read_report(report_id));
create policy authenticated_update_own_confirmation on public.report_confirmations for update to authenticated using(user_id=auth.uid() and public.can_read_report(report_id)) with check(user_id=auth.uid() and public.can_read_report(report_id));
create policy authenticated_delete_own_confirmation on public.report_confirmations for delete to authenticated using(user_id=auth.uid() and public.can_read_report(report_id));grant insert,update,delete on public.report_confirmations to authenticated;
create policy authenticated_insert_admin_escalation on public.report_escalations for insert to authenticated with check(user_id=auth.uid() and public.can_manage_report(report_id));grant insert on public.report_escalations to authenticated;
create policy authenticated_insert_admin_debrief on public.incident_debriefs for insert to authenticated with check(user_id=auth.uid() and public.can_manage_report(report_id) and exists(select 1 from public.reports where id=report_id and status='resolved'));
create policy authenticated_update_admin_debrief on public.incident_debriefs for update to authenticated using(public.can_manage_report(report_id)) with check(public.can_manage_report(report_id));grant insert,update on public.incident_debriefs to authenticated;
create policy authenticated_insert_own_rating on public.report_ratings for insert to authenticated with check(user_id=auth.uid() and public.owns_report(report_id) and exists(select 1 from public.reports where id=report_id and status='resolved'));
create policy authenticated_update_own_rating on public.report_ratings for update to authenticated using(user_id=auth.uid() and public.owns_report(report_id)) with check(user_id=auth.uid() and public.owns_report(report_id));grant insert,update on public.report_ratings to authenticated;
create policy authenticated_select_region_assignments on public.patrol_assignments for select to authenticated using(public.is_region_member(region_id));
create policy authenticated_insert_admin_assignments on public.patrol_assignments for insert to authenticated with check(public.is_region_admin(region_id) and exists(select 1 from public.memberships where region_id=patrol_assignments.region_id and user_id=patrol_assignments.user_id and status='verified'));
create policy authenticated_delete_admin_assignments on public.patrol_assignments for delete to authenticated using(public.is_region_admin(region_id));grant insert,delete on public.patrol_assignments to authenticated;
create policy authenticated_select_own_or_admin_attendance on public.patrol_attendance for select to authenticated using((user_id=auth.uid() and public.is_region_member(region_id)) or public.is_region_admin(region_id));
create policy authenticated_select_participant_swap on public.shift_swap_requests for select to authenticated using(public.is_region_member(region_id) and (user_id=auth.uid() or recipient_id=auth.uid() or public.is_region_admin(region_id)));
create policy authenticated_select_own_or_admin_vote on public.poll_votes for select to authenticated using(public.is_region_member(region_id) and (user_id=auth.uid() or public.is_region_admin(region_id)));
create policy authenticated_insert_own_active_vote on public.poll_votes for insert to authenticated with check(user_id=auth.uid() and public.is_region_member(region_id) and exists(select 1 from public.polls where id=poll_id and region_id=poll_votes.region_id and status='active' and closes_at>now()));grant insert on public.poll_votes to authenticated;
create policy authenticated_select_private_location on public.live_locations for select to authenticated using((user_id=auth.uid() and public.is_region_member(region_id)) or public.is_location_recipient(id));
create policy authenticated_insert_own_location on public.live_locations for insert to authenticated with check(user_id=auth.uid() and public.is_region_member(region_id) and expires_at>now() and expires_at<=now()+interval '24 hours');
create policy authenticated_update_own_location on public.live_locations for update to authenticated using(user_id=auth.uid() and public.is_region_member(region_id)) with check(user_id=auth.uid() and public.is_region_member(region_id) and expires_at<=now()+interval '24 hours');
create policy authenticated_delete_own_location on public.live_locations for delete to authenticated using(user_id=auth.uid() and public.is_region_member(region_id));grant insert,update,delete on public.live_locations to authenticated;
create policy authenticated_select_location_recipients on public.location_recipients for select to authenticated using(public.owns_location_share(share_id) or (user_id=auth.uid() and public.is_region_member(region_id)));
create policy authenticated_insert_location_recipients on public.location_recipients for insert to authenticated with check(public.owns_location_share(share_id) and exists(select 1 from public.memberships where region_id=location_recipients.region_id and user_id=location_recipients.user_id and status='verified'));
create policy authenticated_delete_location_recipients on public.location_recipients for delete to authenticated using(public.owns_location_share(share_id));grant insert,delete on public.location_recipients to authenticated;
create policy authenticated_select_own_preferences on public.notification_preferences for select to authenticated using(user_id=auth.uid() and public.is_region_member(region_id));
create policy authenticated_insert_own_preferences on public.notification_preferences for insert to authenticated with check(user_id=auth.uid() and public.is_region_member(region_id));
create policy authenticated_update_own_preferences on public.notification_preferences for update to authenticated using(user_id=auth.uid() and public.is_region_member(region_id)) with check(user_id=auth.uid() and public.is_region_member(region_id));grant insert,update on public.notification_preferences to authenticated;
create policy authenticated_select_own_notifications on public.notifications for select to authenticated using(user_id=auth.uid() and public.is_region_member(region_id));
create policy authenticated_update_own_notifications on public.notifications for update to authenticated using(user_id=auth.uid() and public.is_region_member(region_id)) with check(user_id=auth.uid() and public.is_region_member(region_id));revoke update on public.notifications from authenticated;grant update(read_at) on public.notifications to authenticated;
create policy authenticated_select_admin_integrations on public.webhook_integrations for select to authenticated using(public.is_region_admin(region_id));
create policy authenticated_insert_admin_integrations on public.webhook_integrations for insert to authenticated with check(user_id=auth.uid() and public.is_region_admin(region_id));
create policy authenticated_update_admin_integrations on public.webhook_integrations for update to authenticated using(public.is_region_admin(region_id)) with check(public.is_region_admin(region_id));
create policy authenticated_delete_admin_integrations on public.webhook_integrations for delete to authenticated using(public.is_region_admin(region_id));grant insert,update,delete on public.webhook_integrations to authenticated;
create policy authenticated_select_admin_webhook_deliveries on public.webhook_deliveries for select to authenticated using(public.is_region_admin(region_id));
-- identitas data dikunci agar update tidak memindahkan pemilik/wilayah.
create or replace function public.lock_record_identity() returns trigger language plpgsql set search_path='' as $$ begin if new.id<>old.id or new.user_id<>old.user_id or new.region_id<>old.region_id or new.created_at<>old.created_at then raise exception 'Identitas data tidak dapat diubah';end if;return new;end; $$;
create or replace function public.lock_report_child_identity() returns trigger language plpgsql set search_path='' as $$ begin if new.id<>old.id or new.user_id<>old.user_id or new.report_id<>old.report_id or new.created_at<>old.created_at then raise exception 'Identitas laporan tidak dapat diubah';end if;return new;end; $$;
create or replace function public.check_request_submission() returns trigger language plpgsql set search_path='' as $$ begin if tg_table_name='payment_confirmations' then if new.admin_note<>'' or new.transaction_id is not null or new.proof_path not like auth.uid()::text||'/%' then raise exception 'Bukti pembayaran harus milik pemohon dan belum ditinjau';end if;elsif tg_table_name='letter_requests' then if new.admin_note<>'' or new.document_path is not null then raise exception 'Dokumen hanya diberikan pengurus';end if;elsif tg_table_name='evacuation_requests' and new.admin_note<>'' then raise exception 'Catatan pengurus tidak boleh diisi pemohon';end if;return new;end; $$;
create trigger check_payment_submission before insert on public.payment_confirmations for each row execute function public.check_request_submission();
create trigger check_letter_submission before insert on public.letter_requests for each row execute function public.check_request_submission();
create trigger check_evacuation_submission before insert on public.evacuation_requests for each row execute function public.check_request_submission();
create or replace function public.audit_region_action() returns trigger language plpgsql security definer set search_path='' as $$ declare row_data jsonb;target_region uuid;begin if auth.uid() is null then if tg_op='DELETE' then return old;else return new;end if;end if;if tg_op='DELETE' then row_data:=to_jsonb(old);else row_data:=to_jsonb(new);end if;target_region:=(row_data->>'region_id')::uuid;if target_region is null and row_data?'report_id' then select region_id into target_region from public.reports where id=(row_data->>'report_id')::uuid;end if;if public.is_region_admin(target_region) then insert into public.audit_logs(region_id,actor_id,action,target_table,target_id) values(target_region,auth.uid(),lower(tg_op),tg_table_name,(row_data->>'id')::uuid);end if;if tg_op='DELETE' then return old;else return new;end if;end; $$;
create or replace function public.enqueue_region_event() returns trigger language plpgsql security definer set search_path='' as $$ declare event_name text;event_title text;event_body text;begin if tg_table_name='sos_alerts' then event_name:='sos_created';event_title:='Sinyal SOS warga';event_body:='Sinyal darurat baru memerlukan respons pengurus';elsif tg_table_name='reports' then event_name:='report_created';event_title:='Laporan baru';event_body:=new.title;else event_name:='early_warning';event_title:=new.title;event_body:=new.body;end if;insert into public.notifications(region_id,user_id,kind,title,body,entity_id) select new.region_id,m.user_id,event_name,event_title,event_body,new.id from public.memberships m left join public.notification_preferences p on p.region_id=m.region_id and p.user_id=m.user_id where m.region_id=new.region_id and m.status='verified' and ((event_name='early_warning' and coalesce(p.emergency_alerts,true)) or (event_name in ('sos_created','report_created') and m.role in ('super_admin','admin')));insert into public.webhook_deliveries(region_id,integration_id,event,entity_id,payload) select new.region_id,w.id,event_name,new.id,jsonb_build_object('event',event_name,'entity_id',new.id,'region_id',new.region_id,'title',event_title,'created_at',new.created_at) from public.webhook_integrations w where w.region_id=new.region_id and w.enabled and event_name=any(w.events);return new;end; $$;
create or replace function public.notify_patrol_assignment() returns trigger language plpgsql security definer set search_path='' as $$ declare s public.patrol_shifts;begin select * into s from public.patrol_shifts where id=new.shift_id;insert into public.notifications(region_id,user_id,kind,title,body,entity_id) values(new.region_id,new.user_id,'patrol_assignment','Jadwal ronda Anda',s.title||' · '||to_char(s.starts_at at time zone 'Asia/Jakarta','dd-mm-yyyy hh24:mi'),new.id);return new;end; $$;
create trigger enqueue_region_event after insert on public.reports for each row execute function public.enqueue_region_event();
create trigger enqueue_region_event after insert on public.sos_alerts for each row execute function public.enqueue_region_event();
create trigger enqueue_region_event after insert on public.early_warnings for each row execute function public.enqueue_region_event();
create trigger notify_patrol_assignment after insert or update of shift_id on public.patrol_assignments for each row execute function public.notify_patrol_assignment();
do $$ declare t text;begin for t in select table_name from information_schema.columns where table_schema='public' and column_name='region_id' intersect select table_name from information_schema.columns where table_schema='public' and column_name='user_id' loop execute format('create trigger lock_record_identity before update on public.%I for each row execute function public.lock_record_identity()',t);end loop;foreach t in array array['report_confirmations','incident_debriefs','report_ratings'] loop execute format('create trigger lock_report_child_identity before update on public.%I for each row execute function public.lock_report_child_identity()',t);end loop;foreach t in array array['reports','sos_alerts','report_categories','report_updates','report_comments','report_escalations','incident_debriefs','early_warnings','announcements','emergency_contacts','water_readings','households','family_members','evacuation_requests','guest_visits','patrol_posts','patrol_shifts','patrol_assignments','inventory_items','assembly_points','logistics_needs','safe_routes','safe_route_points','cash_transactions','payment_confirmations','polls','poll_options','letter_requests','webhook_integrations','mitigation_guides'] loop execute format('create trigger audit_region_action after insert or update or delete on public.%I for each row execute function public.audit_region_action()',t);end loop;end; $$;
-- bucket privat: file biner tidak disimpan di postgres.
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values
('domicile-proofs','domicile-proofs',false,10485760,array['image/jpeg','image/png','image/webp','application/pdf']),
('report-media','report-media',false,52428800,array['image/jpeg','image/png','image/webp','video/mp4','video/quicktime','audio/mp4','audio/m4a','audio/x-m4a','audio/mpeg','audio/wav','audio/webm','video/webm']),
('payment-proofs','payment-proofs',false,10485760,array['image/jpeg','image/png','image/webp','application/pdf']),
('community-documents','community-documents',false,10485760,array['application/pdf','image/jpeg','image/png','image/webp']) on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create policy authenticated_insert_own_domicile on storage.objects for insert to authenticated with check(bucket_id='domicile-proofs' and (storage.foldername(name))[1]=auth.uid()::text);
create policy authenticated_select_own_or_admin_domicile on storage.objects for select to authenticated using(bucket_id='domicile-proofs' and ((storage.foldername(name))[1]=auth.uid()::text or exists(select 1 from public.memberships m where m.domicile_path=objects.name and public.is_region_admin(m.region_id))));
create policy authenticated_insert_own_community_files on storage.objects for insert to authenticated with check(bucket_id in ('report-media','payment-proofs','community-documents') and (storage.foldername(name))[1]=auth.uid()::text and exists(select 1 from public.regions r where r.id::text=(storage.foldername(objects.name))[2] and public.is_region_member(r.id)));
create policy authenticated_select_community_files on storage.objects for select to authenticated using(((storage.foldername(name))[1]=auth.uid()::text and bucket_id in ('report-media','payment-proofs','community-documents')) or (bucket_id='report-media' and exists(select 1 from public.report_media m where m.storage_path=objects.name and public.can_read_report(m.report_id))) or (bucket_id='report-media' and exists(select 1 from public.report_updates u where u.proof_path=objects.name and public.can_read_report(u.report_id))) or (bucket_id='payment-proofs' and exists(select 1 from public.regions r where r.id::text=(storage.foldername(objects.name))[2] and public.is_region_admin(r.id))) or (bucket_id='community-documents' and exists(select 1 from public.letter_requests l where l.document_path=objects.name and ((l.user_id=auth.uid() and public.is_region_member(l.region_id)) or public.is_region_admin(l.region_id)))));
-- execute rpc hanya authenticated; fungsi trigger bukan api publik.
do $$ declare fn record;begin for fn in select p.oid::regprocedure as signature,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('handle_new_user','sync_verified_account','is_super_admin','is_region_member','is_region_admin','can_read_report','can_manage_report','owns_report','owns_location_share','is_location_recipient','create_region','join_region','set_admin_by_email','review_membership','get_region_feed','get_report_detail','get_crowd_summary','get_poll_results','update_report_progress','close_own_sos','review_service_request','review_payment','checkin_patrol','request_shift_swap','respond_shift_swap','log_report_progress','lock_record_identity','lock_report_child_identity','check_request_submission','audit_region_action','enqueue_region_event','notify_patrol_assignment') loop execute format('revoke all on function %s from public,anon,authenticated',fn.signature);if fn.proname not in ('handle_new_user','sync_verified_account','log_report_progress','lock_record_identity','lock_report_child_identity','check_request_submission','audit_region_action','enqueue_region_event','notify_patrol_assignment') then execute format('grant execute on function %s to authenticated',fn.signature);end if;end loop;end; $$;
-- publikasi realtime mempertahankan rls pada semua tabel.
do $$ declare t text;begin if exists(select 1 from pg_publication where pubname='supabase_realtime') then for t in select tablename from pg_tables where schemaname='public' loop if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename=t) then execute format('alter publication supabase_realtime add table public.%I',t);end if;end loop;end if;end; $$;
commit;
